facts.claim:
New serial main-thread work after the join (PR #4901): the note_k_row_saved loop runs once per item with KV work, for every layer of every pass, whenever the operation is not hardware-scored. Exact current code:
      if constexpr (k_vnni::layout_on<geometry.kv.head_size>) {
        if (!cached_operation_uses_hw(binding.operation)) {
          for (token_job_id ix : q_batch->items) {
            auto const& self = *this;
            if (!self.token_jobs_do_kv[ix]) continue;
            const token_id tok_ix = token_jobs[ix];
            page& pg = page_of(tok_ix);
            const size_t j = static_cast<size_t>(pg.offset_in_page(tok_ix));
            if (pg.template note_k_row_saved<geometry.kv>(slot, j)) {
              pending_k_blocks_.push_back({&pg, pg.k_storage_of(slot),
                  static_cast<uint32_t>(j / k_store_block)});
            }
          }
        }
      }

pending_k_blocks_ is one std::vector member of the model state, filled by every save_k of every layer and minibatch of a pass and cleared only in convert_pending_k_blocks at the forward end: the queue is per forward pass, not per layer. Exact current code:
    struct pending_k_block {
      page* pg;
      typename page::k_storage_ref storage;
      uint32_t block;
    };
    std::vector<pending_k_block> pending_k_blocks_;

    void convert_pending_k_blocks() noexcept {
      if (pending_k_blocks_.empty()) return;
      TRACE_EVENT("model", "convert_k_blocks", "blocks", pending_k_blocks_.size());
      for (pending_k_block const& b : pending_k_blocks_) {
        b.pg->k_block_to_vnni_at(b.storage, b.block);
      }
      pending_k_blocks_.clear();
    }

